package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaZhDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_undressing" to DuaText("脱衣服时", "以安拉的名义。", "脱衣服时（大净或换衣服）。", "它成为精灵的眼睛和人的私处之间的屏障。"),
        "dua_ilbas_jadidan" to DuaText("看到有人穿新衣服", "穿新衣，活得值得称赞，死得烈士。", "看到一位穿着新衣服的穆斯林兄弟。", "先知 ﷺ 在看到奥马尔 (RA) 穿着新衣服时做出了这个杜阿。"),
        "dua_hajj_la_riya" to DuaText("不炫耀的朝觐", "安拉啊，朝觐时不炫耀，不求名誉。", "去朝觐时要真诚。", "先知 ﷺ 在朝觐时做出了这个杜阿。"),
        "dua_q_muslimayni_laka" to DuaText("易卜拉欣和伊斯梅尔的杜阿 (AS) — 让我们顺服", "我们的主，求你使我们顺服你，并让我们的子孙后代顺服你。向我们展示我们的敬拜仪式并接受我们的悔改。事实上，您是悔改的接受者，是仁慈的。", "对自己和子孙后代的服从。", "建造天房时制作的杜阿。"),
        "dua_q_iftah_baynana" to DuaText("Shu'aib 的 Dua (AS) — 我们之间的法官", "我们的主，求你在我们和我们的人民之间诚实地审判，你是最好的审判者。", "为了判断真假。", "Shu'ayb (AS) 的杜阿，当时他的人民拒绝了他。"),
        "dua_q_la_akuna_zahiran" to DuaText("Dua of Musa (AS) — 绝不是罪犯的帮手", "主啊，因为您对我的恩惠，我永远不会成为罪犯的帮手。", "感谢真主的祝福并承诺不帮助不法之徒。", "穆萨(AS)悔改后的誓言。"),
        "dua_q_nuh_unsurni" to DuaText("Dua of Nuh (AS) — 帮助我，他们否认我", "我的主啊，请帮助我，因为他们拒绝了我。", "当人们否认你并拒绝真理时。", "Nuh (AS) 的二重奏已得到答复。"),
        "dua_q_ihkum_bil_haqq" to DuaText("我的主啊，请以真理审判", "主啊，请按真理审判。我们的主是最仁慈的，我们针对你所描述的情况寻求他的帮助。", "面对谎言和不实指控。", "向先知 ﷺ 教导的杜阿。"),
        "dua_ghalabatid_dayn" to DuaText("逃离沉重的债务和敌人", "安拉啊，我向你寻求庇护，免遭债务的压垮、被敌人的压倒和敌人的幸灾乐祸。", "免受债务负担和敌人统治的保护。", "先知 ﷺ 曾经寻求庇护以避免这些事情。"),
        "dua_faqr_qillah_dhillah" to DuaText("摆脱贫穷和屈辱", "安拉啊，我向你寻求庇护，使我免遭贫穷、匮乏和羞辱，免遭冤枉他人或被冤屈。", "远离困难、匮乏和羞辱。", "先知 ﷺ 教导的避难所。"),
        "dua_five_things_new_muslim" to DuaText("宽恕、怜悯、引导、治愈、提供", "安拉啊，宽恕我，怜悯我，引导我，赐予我幸福，供养我。", "先知 ﷺ 向新穆斯林教导了这个杜阿以及祈祷文。", "先知 ﷺ 说：这些话为你收集今世和后世。"),
        "dua_ruku_laka_raka_tu" to DuaText("In Ruku——我向你鞠躬", "安拉啊，我向你顶礼，我相信你，我已经顺服你。我的听觉、我的视觉、我的思想、我的骨头和我的肌腱都在你面前谦卑。", "在 ruku 中（特别是在自愿祈祷中）。", "先知 ﷺ 用 ruku 背诵了这一点。"),
        "dua_sujood_laka_sajadtu" to DuaText("在Sujood——我向你跪拜", "安拉啊，我向你顶礼，我相信你，我向你屈服。我的脸已经向创造它、塑造它并带来它的听觉和视觉的那一位俯首称臣。真主是有福的，他是最优秀的创造者。", "在sujood中（特别是在自愿祈祷中）。", "先知 ﷺ 在 sujood 中背诵了这一点。"),
        "dua_ruku_sujood_subhanaka" to DuaText("荣耀归于你，我们的主——请原谅我", "真主啊，我们的主啊，荣耀归于你，赞美归于你。安拉啊，请原谅我。", "在 ruku 和 sujood 中。", "艾莎 (RA)：先知 ﷺ 经常在 ruku 和 sujood 中这么说。"),
        "dua_q_musa_li_akhi" to DuaText("穆萨的杜阿 (AS) — 原谅我和我的兄弟", "我的主啊，请原谅我和我的兄弟，并让我们接受您的仁慈，因为您是仁慈者中最仁慈的。", "宽恕自己和自己的兄弟或亲人。", "穆萨 (AS) 与哈伦 (AS) 的二重奏。"),
        "dua_q_ufawwidu_amri" to DuaText("我将我的事情托付给真主", "我将我的事情托付给真主。的确，安拉是全视他的仆人的。", "当人们反对你时，事情必须留给安拉。", "法老百姓信徒的话；安拉随后保护他免受他们的邪恶阴谋的侵害。"),
        "dua_q_hawariyyun" to DuaText("门徒们的杜阿——记录我们与见证者", "我们的主啊，我们相信您所启示的一切，我们也追随使者，所以请将我们记录在证人之中。", "坚定信仰并追随使者。", "以赛亚 (AS) 门徒的杜阿。"),
        "dua_q_la_tukhzini" to DuaText("易卜拉欣的杜阿 (AS) — 不要羞辱我", "在他们复活的那一天，不要让我蒙羞。", "在复活日免遭羞辱。", "易卜拉欣的二重奏 (AS) 为来世。"),
        "dua_iftar_laka_sumtu" to DuaText("开斋饭——我为你禁食", "安拉啊，我为你封斋，并在你的供应下我开斋。", "开斋时（著名的开斋节）。", "先知 ﷺ 在开斋节上这么说。这是一种由其他叙述强化的壁画叙述；在开斋节上背诵这句话是哈纳菲派和大多数人的做法。"),
        "dua_iftar_ibn_umar" to DuaText("开斋饭——以您的慈悲，请原谅我", "安拉啊，我请求您以包容万物的仁慈宽恕我。", "在开斋节上 — Abdullah ibn Amr (RA) 做了这道 dua；斋戒者在开斋节上的杜阿不会被拒绝。", "圣训：斋戒者在开斋时的杜阿不会被拒绝。"),
        "dua_inni_saim" to DuaText("禁食期间被激怒时", "我在斋戒，我在斋戒。", "当有人在禁食期间侮辱你或与你争吵时。", "先知ﷺ说：斋戒是盾牌，所以斋戒的人不应该说下流的话或做出无知的行为——如果有人吵架，就说两遍。"),
        "dua_eid_takbeer" to DuaText("前往开斋节的路上的塔克比尔", "安拉是至大的，安拉是至大的，除安拉外，绝无应受崇拜的，安拉是至大的，安拉是至大的，一切赞美归于安拉。", "从观月之夜到开斋节祈祷，尤其是前往开斋节的路上。", "《古兰经》命令：“以便你们完成计数并宣扬安拉的伟大”（al-Baqarah 2:185）。 Ibn Mas'ud (RA) 说了这句话。"),
        "dua_ahsin_aqibatana" to DuaText("凡事善终", "安拉啊，请使我们在所有事情上都有美好的结局，并保护我们免受今世的耻辱和后世的惩罚。", "为了每件事都能有好的结果。", "无论谁做出这个杜阿并在受审前死亡（免受审判）。"),
        "dua_fadlika_wa_rahmatik" to DuaText("我请求你的慷慨和怜悯", "安拉啊，我向你祈求你的恩惠和仁慈，因为除了你之外，没有人拥有它们。", "当请求供给和怜悯时。", "客人来先知ﷺ时没有食物；他做了这个杜阿，然后礼物就到了。"),
        "dua_allahu_akbar_kabira_2696" to DuaText("教给贝都因人的话", "除了真主之外，没有人有权利被崇拜，独自一人，没有伴侣。安拉是最伟大的；对真主的赞美是无穷无尽的；荣耀归于真主，世界之主；除了安拉、全能者、至睿者之外，没有任何力量和力量。", "dhikr 和 dua 的综合短语——教给贝都因人。", "此后，他被教导说“Allahummaghfir li warhamni wahdini warzuqni”。"),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("原谅我之前和之后发送的内容", "安拉啊，宽恕我之前和之后犯下的罪孽，宽恕我秘密和公开的所作所为，宽恕我的过激行为，以及您比我更了解的事情。你是推动者，也是推动者；除了你之外，再没有神。", "在 tashahhud 和 salawat 之后，在 salam 之前。", "先知 ﷺ 在祈祷结束时、在 tashahhud 和 salam 之间背诵了这句话。"),
        "dua_jiddi_wa_hazli" to DuaText("原谅我的认真和我的玩笑", "安拉啊，请宽恕我犯下的那些严重的、开玩笑的、错误的和故意的罪行——所有这些都在我身上。", "宽恕各种已知和未知的罪恶。", "先知 ﷺ 的综合内容。"),
        "dua_rising_ruku_mil" to DuaText("Ruku之后——赞美充满天堂", "我们的主，一切赞美都归于你，充满诸天，充满大地，充满你之后所要的一切。", "从 ruku 崛起后，与“Rabbana lakal-hamd”一起。", "先知 ﷺ 在从 ruku 升起时这样说。"),
        "dua_istiftah_kabira" to DuaText("真主至大，万受赞颂", "安拉是最伟大的；对真主的赞美是无穷无尽的；早晚荣耀归于真主。", "开始祈祷时（开头赞美的一种形式）。", "先知 ﷺ 说：天堂之门已为它打开。"),
        "dua_q_ashku_bathhi" to DuaText("Dua of Yaqub (AS) — 我只向真主抱怨", "我只向阿拉抱怨我的痛苦和悲伤。", "陷入深深的悲伤和分离之中。", "Ya'qub (AS) 在与 Yusuf (AS) 分手时这么说。"),
        "dua_q_khayrun_hafiza" to DuaText("安拉是最好的保护者", "安拉是最好的保护者，他是最仁慈的人。", "送孩子或亲人旅行时。", "Ya'qub (AS) 在将他的儿子托付给真主时说了这番话。"),
        "dua_q_aqraba_rashada" to DuaText("愿我的主引导我更接近正确的方向", "也许我的主会引导我做比这更接近正确行为的事情。", "在某些事情上寻求更好的方法时。", "先知 ﷺ 被告知在忘记时说这句话。"),
        "dua_q_sawa_as_sabil" to DuaText("Dua of Musa (AS) — 引导我走向正确的道路", "也许我的主会引导我走上正确的道路。", "当踏上新的旅程或陌生的道路时。", "穆萨(AS)一边说着，一边转向了马迪安。"),
        "dua_q_not_among_wrongdoers" to DuaText("不要将我置于不法之徒之中", "主啊，请不要将我置于不法之人之中。", "杜阿请求安拉将一个人与不法之徒分开。", "杜阿请求安拉将一个人与不法之徒分开。"),
        "dua_q_do_not_make_us_trial" to DuaText("不要让我们受到考验", "我们的主啊，不要让我们成为不信道者的考验，请原谅我们，我们的主。诚然，祢是全能者、至睿者。", "易卜拉欣 (AS) 和他的同伴的杜阿。", "易卜拉欣 (AS) 和他的同伴的杜阿。"),
        "dua_morning_witness" to DuaText("晨间见证Tawhid", "安拉啊，我进入清晨，呼唤你，你宝座的承载者，你的天使和你的一切创造物，见证你是安拉，除了你，没有神，孤独，没有伙伴，穆罕默德ﷺ是你的仆人和使者。", "旁白提到早上说了四次。", "旁白提到早上说了四次。"),
        "dua_evening_witness" to DuaText("晚间见证Tawhid", "安拉啊，我已进入傍晚，呼唤你，你宝座的承载者，你的天使和你所有的创造物，见证你是安拉，除了你，没有神，孤独，没有伙伴，穆罕默德ﷺ是你的仆人和使者。", "旁白提到晚上说了四次。", "旁白提到晚上说了四次。"),
        "dua_morning_blessing" to DuaText("早上好，谢谢你的祝福", "安拉啊，无论我或你的任何创造物今天早上收到什么祝福，都只来自于你，没有伙伴；所以所有的赞美和感谢都属于你。", "晨祷，感谢安拉的祝福。", "晨祷，感谢安拉的祝福。"),
        "dua_evening_blessing" to DuaText("晚上谢谢大家的祝福", "安拉啊，无论我或你的任何创造物今晚收到什么祝福，都只来自于你，没有伙伴；所以所有的赞美和感谢都属于你。", "晚间感恩真主的祝福。", "晚间感恩真主的祝福。"),
    )
}
